        <div class="flex flex-wrap gap-2"><button v-if="item.can_update_status" type="button" class="hero-primary" @click="openStatus"><span class="material-icons text-lg">published_with_changes</span>Update Status</button><Link :href="item.related_url" class="hero-secondary"><span class="material-icons text-lg">open_in_new</span>Buka {{ item.type === 'ticket' ? 'Ticket' : 'Task' }}</Link><Dropdown v-if="item.can_update_workflow || item.can_toggle_workflow" width-class="w-52" trigger-class="inline-flex items-center justify-center rounded-xl border border-white/20 bg-white/10 px-3 py-2.5 text-slate-100 hover:bg-white/15"><template #trigger><span class="material-icons">more_horiz</span></template><Link v-if="item.can_update_workflow" :href="item.workflow_edit_url" class="menu"><span class="material-icons">schema</span>Edit struktur</Link><Link v-if="item.can_view_workflow" :href="item.workflow_url" class="menu"><span class="material-icons">account_tree</span>Definisi workflow</Link><button v-if="item.can_toggle_workflow" class="menu w-full" type="button" @click="confirmToggle"><span class="material-icons">power_settings_new</span>{{ item.workflow_active ? 'Nonaktifkan' : 'Aktifkan' }}</button></Dropdown></div>
