    <section class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      <article class="metric"><div class="metric-icon bg-cyan-50 text-cyan-600 dark:bg-cyan-500/10"><span class="material-icons">radar</span></div><div><p>Status Saat Ini</p><strong>{{ item.status_label }}</strong><span>{{ item.stage_name }}</span></div></article>
      <article class="metric"><div class="metric-icon bg-violet-50 text-violet-600 dark:bg-violet-500/10"><span class="material-icons">flag</span></div><div><p>Prioritas</p><strong class="capitalize">{{ item.priority }}</strong><span>Target {{ formatDate(item.target_date, false) }}</span></div></article>
      <article class="metric"><div class="metric-icon" :class="slaTone"><span class="material-icons">timer</span></div><div><p>SLA</p><strong>{{ item.sla.label }}</strong><span>{{ slaStateLabel }}</span></div></article>
      <article class="metric"><div class="metric-icon bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10"><span class="material-icons">route</span></div><div><p>Progress</p><strong>{{ progressPercent }}%</strong><span>{{ completedStages }} dari {{ item.timeline.length }} tahap</span></div></article>
    </section>

    <section class="grid gap-6 xl:grid-cols-[1.4fr_.9fr]">
      <article class="card"><div class="section-head"><div><p class="eyebrow">Runtime Profile</p><h2>Informasi {{ item.type === 'ticket' ? 'Ticket' : 'Task' }}</h2></div><span class="material-icons text-cyan-500">dataset</span></div><dl class="info-grid"><div><dt>Nomor</dt><dd class="font-mono text-cyan-700 dark:text-cyan-300">{{ item.number }}</dd></div><div><dt>Workflow</dt><dd>{{ item.workflow_name }}</dd></div><div><dt>Requester</dt><dd>{{ item.requester }}</dd></div><div><dt>Creator</dt><dd>{{ item.creator }}</dd></div><div><dt>PIC / Assignee</dt><dd>{{ item.pic }}</dd></div><div><dt>Tipe</dt><dd class="capitalize">{{ item.related.type || item.type }}</dd></div><div><dt>Dibuat</dt><dd>{{ formatDate(item.created_at) }}</dd></div><div><dt>Diperbarui</dt><dd>{{ formatDate(item.updated_at) }}</dd></div></dl><div class="mt-5 rounded-2xl border border-slate-200 bg-slate-50/70 p-4 dark:border-slate-700 dark:bg-slate-800/60"><p class="label">Deskripsi</p><p class="mt-2 whitespace-pre-line text-sm leading-relaxed text-slate-600 dark:text-slate-300">{{ item.description || 'Tidak ada deskripsi.' }}</p></div></article>
      <article class="card"><div class="section-head"><div><p class="eyebrow">Service Window</p><h2>SLA & Timeline Waktu</h2></div><span class="material-icons text-violet-500">schedule</span></div><div class="mt-5 space-y-4"><div class="time-row"><span class="dot bg-cyan-500"></span><div><p>Workflow dimulai</p><strong>{{ formatDate(item.sla.started_at) }}</strong></div></div><div class="time-row"><span class="dot" :class="item.sla.state === 'overdue' ? 'bg-rose-500' : 'bg-amber-500'"></span><div><p>Target penyelesaian</p><strong>{{ formatDate(item.sla.target_at) }}</strong></div></div><div class="time-row"><span class="dot bg-emerald-500"></span><div><p>Waktu selesai</p><strong>{{ formatDate(item.sla.finished_at) }}</strong></div></div></div><div class="mt-5 rounded-2xl p-4" :class="slaPanelTone"><p class="text-xs font-bold uppercase tracking-wider">Kondisi SLA</p><p class="mt-1 text-sm font-semibold">{{ slaStateLabel }}</p></div><div v-if="item.related.parent_number" class="mt-5 border-t border-slate-200 pt-5 dark:border-slate-700"><p class="label">Ticket induk</p><Link :href="item.related.parent_url" class="mt-2 block rounded-xl border border-cyan-200 bg-cyan-50 p-3 hover:border-cyan-400 dark:border-cyan-500/20 dark:bg-cyan-500/5"><span class="font-mono text-xs font-bold text-cyan-700 dark:text-cyan-300">{{ item.related.parent_number }}</span><p class="mt-1 text-sm font-semibold text-slate-800 dark:text-white">{{ item.related.parent_title }}</p></Link></div><div v-else-if="item.type === 'ticket'" class="mt-5 border-t border-slate-200 pt-5 dark:border-slate-700"><p class="label">Relasi Ticket</p><p class="mt-2 text-sm text-slate-600 dark:text-slate-300">{{ item.related.tasks_count }} task terkait<span v-if="item.related.reason"> · {{ item.related.reason }}</span></p></div></article>
    </section>

    <section class="card overflow-hidden !p-0"><div class="section-head border-b border-slate-200 px-5 py-4 dark:border-slate-700 sm:px-6"><div><p class="eyebrow">Execution Path</p><h2>Workflow Progress</h2><p class="mt-1 text-sm font-normal text-slate-500">Tahapan berurutan, penanggung jawab, catatan, dan waktu aktual.</p></div><span class="rounded-full bg-cyan-50 px-3 py-1 text-xs font-bold text-cyan-700 dark:bg-cyan-500/10 dark:text-cyan-300">{{ item.stage_name }} aktif</span></div><ol class="timeline px-5 py-6 sm:px-7"><li v-for="(stage,index) in item.timeline" :key="stage.id" class="timeline-item" :class="`is-${stage.state}`"><div class="timeline-rail"><span class="timeline-node"><span class="material-icons">{{ stage.state === 'completed' ? 'check' : stage.state === 'active' ? 'bolt' : 'circle' }}</span></span><span v-if="index < item.timeline.length - 1" class="timeline-line"></span></div><article class="timeline-card"><div class="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><div class="flex flex-wrap items-center gap-2"><span class="text-xs font-bold text-slate-400">{{ String(stage.position).padStart(2, '0') }}</span><h3 class="font-bold text-slate-900 dark:text-white">{{ stage.name }}</h3><span class="stage-state">{{ stageStateLabel(stage.state) }}</span><span :class="stage.is_required ? 'bg-rose-50 text-rose-700 dark:bg-rose-500/10 dark:text-rose-300' : 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-300'" class="rounded-full px-2 py-0.5 text-[10px] font-bold uppercase">{{ stage.is_required ? 'Wajib' : 'Opsional' }}</span></div><p class="mt-1 text-xs font-semibold text-cyan-600 dark:text-cyan-300">{{ stage.status_label }}</p></div><div class="text-left text-xs text-slate-500 sm:text-right"><p>Masuk: {{ formatDate(stage.entered_at) }}</p><p class="mt-1">Selesai: {{ formatDate(stage.completed_at) }}</p></div></div><div class="mt-4 grid gap-3 text-sm sm:grid-cols-2"><div class="mini-info"><span class="material-icons">badge</span><div><p>Penanggung jawab</p><strong>{{ stage.responsible_user || stage.responsible_role || 'Dinamis' }}</strong><small v-if="stage.responsible_user && stage.responsible_role">Role {{ stage.responsible_role }}</small></div></div><div class="mini-info"><span class="material-icons">notes</span><div><p>Catatan / Aksi</p><strong>{{ stage.notes || stage.action_label || 'Tidak ada catatan' }}</strong></div></div></div></article></li></ol></section>

    <section class="grid gap-6 lg:grid-cols-[1fr_320px]"><article class="card"><div class="section-head"><div><p class="eyebrow">Immutable Trail</p><h2>History & Audit Activity</h2></div><span class="material-icons text-cyan-500">history</span></div><div v-if="!item.history.length" class="mt-6 rounded-2xl border border-dashed border-slate-300 p-8 text-center text-sm text-slate-500 dark:border-slate-700">Belum ada aktivitas runtime.</div><ol v-else class="mt-5 space-y-3"><li v-for="history in item.history" :key="history.id" class="flex gap-3 rounded-2xl border border-slate-200 p-4 dark:border-slate-700"><span class="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-cyan-50 text-cyan-600 dark:bg-cyan-500/10"><span class="material-icons text-lg">{{ history.event === 'started' ? 'play_arrow' : 'swap_horiz' }}</span></span><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center justify-between gap-2"><p class="text-sm font-bold capitalize text-slate-800 dark:text-white">{{ history.event.replaceAll('_', ' ') }}</p><time class="text-xs text-slate-400">{{ formatDate(history.created_at) }}</time></div><p class="mt-1 text-xs text-slate-500">{{ history.actor_name }}</p><p class="mt-2 text-sm text-cyan-700 dark:text-cyan-300">{{ history.from_stage || 'Workflow dimulai' }} <span class="mx-1 text-slate-400">→</span> {{ history.to_stage }}</p></div></li></ol></article><aside class="card h-fit"><p class="eyebrow">Quick Actions</p><h2 class="mt-1 text-lg font-bold dark:text-white">Tindakan Tersedia</h2><div class="mt-5 space-y-2"><button v-if="item.can_update_status" type="button" class="quick primary w-full" @click="openStatus"><span class="material-icons">published_with_changes</span>Update tahap/status</button><Link :href="item.related_url" class="quick secondary w-full"><span class="material-icons">open_in_new</span>Buka item terkait</Link><Link v-if="item.can_edit" :href="item.edit_url" class="quick secondary w-full"><span class="material-icons">edit</span>Edit item terkait</Link><Link v-if="item.can_view_workflow" :href="item.workflow_url" class="quick secondary w-full"><span class="material-icons">account_tree</span>Lihat definisi workflow</Link><Link v-if="item.can_update_workflow" :href="item.workflow_edit_url" class="quick secondary w-full"><span class="material-icons">schema</span>Kelola struktur</Link></div><p v-if="!item.can_update_status" class="mt-4 rounded-xl bg-slate-50 p-3 text-xs leading-relaxed text-slate-500 dark:bg-slate-800">Tidak ada transisi status yang valid atau Anda tidak memiliki izin runtime saat ini.</p></aside></section>

    <Teleport to="body"><Transition name="modal-fade"><div v-if="statusModal" class="modal-layer" role="presentation" @click.self="closeStatus"><form class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="status-modal-title" @submit.prevent="saveStatus"><div class="modal-head"><div><p class="eyebrow">Runtime Action</p><h3 id="status-modal-title">Update Tahap / Status</h3></div><button type="button" class="close" aria-label="Tutup modal" @click="closeStatus">×</button></div><div class="mt-4 rounded-2xl bg-slate-50 p-4 dark:bg-slate-800"><p class="font-mono text-xs font-bold text-cyan-600">{{ item.number }}</p><p class="mt-1 text-sm font-semibold text-slate-800 dark:text-white">{{ item.title }}</p><p class="mt-2 text-xs text-slate-500">Saat ini: {{ item.stage_name }} · {{ item.status_label }}</p></div><label class="field mt-5">Status tujuan<select v-model="statusForm.status" required autofocus class="input"><option value="" disabled>Pilih transisi yang tersedia</option><option v-for="option in item.status_options" :key="option.value" :value="option.value">{{ option.label }}</option></select><small v-if="statusForm.errors.status" class="text-rose-600">{{ statusForm.errors.status }}</small></label><div class="modal-actions"><button type="button" class="secondary" @click="closeStatus">Batal</button><button :disabled="statusForm.processing" class="primary"><span v-if="statusForm.processing" class="spinner"></span>{{ statusForm.processing ? 'Memproses...' : 'Simpan Perubahan' }}</button></div></form></div></Transition><Transition name="modal-fade"><div v-if="confirmation" class="modal-layer" @click.self="confirmation = false"><div class="modal-panel" role="alertdialog" aria-modal="true"><span class="material-icons rounded-2xl bg-amber-50 p-3 text-amber-600">power_settings_new</span><h3 class="mt-4 text-xl font-bold dark:text-white">{{ item.workflow_active ? 'Nonaktifkan workflow?' : 'Aktifkan workflow?' }}</h3><p class="mt-2 text-sm leading-relaxed text-slate-500">Instance, history, Ticket, dan Task tetap tersimpan. Perubahan hanya memengaruhi status definisi workflow.</p><div class="modal-actions"><button type="button" class="secondary" @click="confirmation = false">Batal</button><button type="button" :disabled="toggleBusy" class="primary" @click="toggleWorkflow">{{ toggleBusy ? 'Memproses...' : 'Lanjutkan' }}</button></div></div></div></Transition></Teleport>
  </div>
</template>

<script setup>
import { Link, router, useForm, usePage } from '@inertiajs/vue3'
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import Dropdown from '../../Components/Dropdown.vue'
import AppLayout from '../../Layouts/AppLayout.vue'
import resolveRoute from '../../utils/resolveRoute'
defineOptions({ layout: AppLayout })
const props = defineProps({ item: { type: Object, required: true }, workflow: { type: Object, required: true } })
const page = usePage(), statusModal = ref(false), confirmation = ref(false), toggleBusy = ref(false), notice = ref(null)
const statusForm = useForm({ status: '' })
const completedStages = computed(() => props.item.timeline.filter(stage => stage.state === 'completed').length)
const progressPercent = computed(() => props.item.status === 'done' ? 100 : (props.item.timeline.length ? Math.round((completedStages.value + (props.item.timeline.some(stage => stage.state === 'active') ? .5 : 0)) / props.item.timeline.length * 100) : 0))
const slaStateLabel = computed(() => ({ completed: 'Selesai', cancelled: 'Dibatalkan', overdue: 'Melewati target', on_track: 'Dalam target', not_set: 'Target belum ditentukan' }[props.item.sla.state] || props.item.sla.state))
const slaTone = computed(() => props.item.sla.state === 'overdue' ? 'bg-rose-50 text-rose-600 dark:bg-rose-500/10' : props.item.sla.state === 'completed' ? 'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10' : 'bg-amber-50 text-amber-600 dark:bg-amber-500/10')
const slaPanelTone = computed(() => props.item.sla.state === 'overdue' ? 'bg-rose-50 text-rose-700 dark:bg-rose-500/10 dark:text-rose-300' : props.item.sla.state === 'completed' ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-300' : 'bg-amber-50 text-amber-700 dark:bg-amber-500/10 dark:text-amber-300')
const modalOpen = computed(() => statusModal.value || confirmation.value)
watch(modalOpen, value => { if (typeof document === 'undefined') return; document.documentElement.classList.toggle('workflow-modal-open', value); document.body.classList.toggle('workflow-modal-open', value) }, { immediate: true })
watch(() => [page.props.flash?.success, page.props.flash?.error], ([success, error]) => { const message = error || success; if (!message) return; notice.value = { type: error ? 'error' : 'success', message }; setTimeout(() => { notice.value = null }, 3500) }, { immediate: true })
onBeforeUnmount(() => { if (typeof document === 'undefined') return; document.documentElement.classList.remove('workflow-modal-open'); document.body.classList.remove('workflow-modal-open') })
const openStatus = () => { statusForm.reset(); statusForm.clearErrors(); statusModal.value = true }
const closeStatus = () => { if (!statusForm.processing) statusModal.value = false }
const saveStatus = () => statusForm.patch(props.item.status_update_url, { preserveScroll: true, onSuccess: () => { statusModal.value = false }, onError: () => { notice.value = { type: 'error', message: 'Status gagal diperbarui. Periksa transisi dan izin Anda.' } } })
const confirmToggle = () => { confirmation.value = true }
const toggleWorkflow = () => { toggleBusy.value = true; router.patch(props.item.workflow_toggle_url, {}, { preserveScroll: true, onSuccess: () => { confirmation.value = false }, onFinish: () => { toggleBusy.value = false } }) }
const stageStateLabel = state => ({ active: 'Aktif', completed: 'Terlewati', pending: 'Menunggu' }[state] || state)
const formatDate = (value, includeTime = true) => value ? new Intl.DateTimeFormat('id-ID', includeTime ? { dateStyle: 'medium', timeStyle: 'short' } : { dateStyle: 'medium' }).format(new Date(value)) : '—'
</script>

